export function renderCatalogModule(simpleIconsLibrary, phosphorLibrary) {
  return [
    '// Generated by scripts/generate-icon-catalog.mjs. Do not edit.',
    '// Regenerate after updating the pinned icon packages.',
    '// Keep catalog data out of bundlers’ object-literal ASTs; decode once on lazy import.',
    `export const simpleIconsLibrary = JSON.parse(${JSON.stringify(JSON.stringify(simpleIconsLibrary))});`,
    `export const phosphorLibrary = JSON.parse(${JSON.stringify(JSON.stringify(phosphorLibrary))});`,
    '',
  ].join('\n');
}
